#include <iostream>
struct Node { int val; Node* next; };
int main() {
    Node c{3, nullptr}, b{2, &c}, a{1, &b};
    Node* prev = nullptr;
    Node* cur = &a;
    while (cur) { Node* nx = cur->next; cur->next = prev; prev = cur; cur = nx; }
    for (Node* p = prev; p; p = p->next) std::cout << p->val;
    std::cout << "\n";
    return 0;
}

#include <iostream>
struct Node { int val; Node* next; };
int len(Node* p) {
    int n = 0;
    while (p) { n++; p = p->next; }
    return n;
}
int main() {
    Node b{5, nullptr}, a{7, &b};
    std::cout << len(&a) << "\n";
    return 0;
}

#include <iostream>
struct Node { int val; Node* next; };
int main() {
    Node d{4, nullptr}, c{3, &d}, b{2, &c}, a{1, &b};
    d.next = &b;
    Node* slow = &a, *fast = &a;
    int steps = 0;
    do { slow = slow->next; fast = fast->next->next; steps++; } while (slow != fast);
    std::cout << steps << "\n";
    return 0;
}

#include <iostream>
struct Node { int val; Node* next; };
int main() {
    Node b{2, nullptr};
    Node* head = &b;
    Node n{9, nullptr};
    n.next = head;
    head = &n;
    std::cout << head->val << head->next->val << "\n";
    return 0;
}
